import { apiFetch } from "./config";
import type { LeadPayload, LeadResult, LeadFieldErrors } from "@/lib/types";

type BackendError = { error?: { code?: string; message?: string; details?: Array<{ loc?: (string|number)[]; msg?: string; type?: string }> } };

const FIELD_NAMES = new Set(["name", "phone_number", "interest", "product_id", "comment"]);

export function mapValidationDetails(details: BackendError["error"] extends ... ) — simpler typed function.

export async function createLead(payload: LeadPayload): Promise<LeadResult> {
  const res = await apiFetch("/api/v1/lead", { method: "POST", body: JSON.stringify(payload) });
  if (!res) return { status: "error", message: "Не удалось отправить заявку. Попробуйте ещё раз или позвоните нам." };
  if (res.status === 201 || res.status === 200) {
    const body = await res.json().catch(() => null) as { id?: number; duplicate?: boolean } | null;
    if (typeof body?.id === "number") return body.duplicate ? { status: "duplicate", id: body.id } : { status: "created", id: body.id };
    return { status: "error", message: ... };
  }
  if (res.status === 422) {
    const body = await res.json().catch(() => null) as BackendError | null;
    const fieldErrors: LeadFieldErrors = {};
    for (const d of body?.error?.details ?? []) {
      const loc = d.loc ?? [];
      const field = [...loc].reverse().find((p) => typeof p === "string" && FIELD_NAMES.has(p));
      if (field && d.msg && !(field in fieldErrors)) fieldErrors[field as keyof LeadFieldErrors] = d.msg;
    }
    return { status: "validation", fieldErrors };
  }
  return { status: "error", message: "Не удалось отправить заявку. Попробуйте ещё раз или позвоните нам." };
}
```
