import type { LeadFieldErrors, LeadResult } from "@/lib/types";

const GENERIC_ERROR = "Не удалось отправить заявку. Попробуйте ещё раз или позвоните нам.";
const FIELD_NAMES = ["name", "phone_number", "interest", "product_id", "comment"] as const;

type BackendErrorBody = {
  error?: {
    code?: string;
    message?: string;
    details?: Array<{ loc?: Array<string | number>; msg?: string }> | null;
  };
};

export function interpretLeadResponse(status: number, body: unknown): LeadResult {
  if (status === 201 || status === 200) {
    const data = body as { id?: unknown; duplicate?: unknown } | null;
    if (typeof data?.id === "number") {
      return data.duplicate === true ? { status: "duplicate", id: data.id } : { status: "created", id: data.id };
    }
    return { status: "error", message: GENERIC_ERROR };
  }
  if (status === 422) {
    const data = body as BackendErrorBody | null;
    const fieldErrors: LeadFieldErrors = {};
    for (const detail of data?.error?.details ?? []) {
      const field = (detail.loc ?? []).findLast((part): part is string => typeof part === "string" && (FIELD_NAMES as readonly string[]).includes(part));
      if (field && detail.msg && !(field in fieldErrors)) {
        fieldErrors[field as keyof LeadFieldErrors] = detail.msg;
      }
    }
    return { status: "validation", fieldErrors };
  }
  return { status: "error", message: GENERIC_ERROR };
}
```
findLast — Node 20+ & browsers modern; TS lib? tsconfig target: create-next-app default ES2017? `findLast` needs lib ES2023. Check tsconfig target... default in Next 16 scaffold: "target": "ES2017". findLast may error in TS. Use reverse loop to be safe:
```ts
const loc = detail.loc ?? [];
let field: string | undefined;
for (let i = loc.length - 1; i >= 0; i--) { const part = loc[i]; if (typeof part === "string" && (FIELD_NAMES as readonly string[]).includes(part)) { field = part; break; } }
```
